"use client";

import { useCallback, useEffect, useRef, useState, type FormEvent, type ReactNode } from "react";
import Link from "next/link";
import type { ActionResponse, ModuleId, PortalSnapshot, SessionResponse, SessionUser } from "@/lib/portal-types";

type InternalModule = Exclude<ModuleId, "public" | "customer">;
type Choice = { value: string; label: string };
type Field = { name: string; label: string; type?: "text" | "email" | "date" | "month" | "number" | "textarea" | "datetime-local" | "multiselect"; options?: Choice[]; required?: boolean; min?: number; max?: number; step?: number; scale?: number; value?: string; hint?: string };
type RecordRow = Record<string, unknown>;
type Column = { key: string; label: string; money?: boolean; date?: boolean };

const moduleInfo: Record<InternalModule, { title: string; description: string; roles: string[] }> = {
  notifications: { title: "Your workspace", description: "Follow the work that needs your attention.", roles: [] },
  finance: { title: "Accounting", description: "Record transactions, check balances and match payment evidence.", roles: ["finance", "finance-director"] },
  hr: { title: "People and HR", description: "Manage employee records, leave, attendance and payroll preparation.", roles: ["hr", "hr-director"] },
  procurement: { title: "Orders, procurement and stock", description: "Progress customer orders and control purchasing and stock movements.", roles: ["sales", "procurement", "storekeeper", "operations-director", "branch-manager", "finance-director"] },
  admin: { title: "Organisation and access", description: "Manage operating units, access requests, tasks and audit evidence.", roles: ["administrator", "operations-director", "branch-manager", "finance-director", "hr-director", "ceo"] },
  communications: { title: "Customer communications", description: "Prepare and capture email campaigns with consent controls.", roles: ["communications", "operations-director"] },
};
const money = (value: unknown) => `MWK ${Number(value ?? 0).toLocaleString("en-GB", { maximumFractionDigits: 0 })}`;
const today = () => new Date().toISOString().slice(0, 10);
const text = (value: unknown) => value == null ? "—" : Array.isArray(value) ? value.map(String).join(", ") || "—" : typeof value === "boolean" ? value ? "Yes" : "No" : String(value);
const names = (items: { id: string; name?: string }[] = [], label?: (item: { id: string; name?: string }) => string): Choice[] => items.map(item => ({ value: item.id, label: label ? label(item) : `${item.name ?? item.id} · ${item.id}` }));
const states = (values: string[]): Choice[] => values.map(value => ({ value, label: value }));
const amountField = (name = "amount", label = "Amount (MWK)", min = 1): Field => ({ name, label, type: "number", min });
const evidenceField: Field = { name: "evidence", label: "Evidence reference", hint: "Use a demonstration reference, never a password or bank credential." };
const campaignTemplates: Record<string, { subject: string; body: string }> = {
  "Product update": { subject: "Your Fatima Agro product enquiry", body: "Hello {{name}},\n\nBrowse the demonstration catalogue and send an enquiry for the products you need. Our team must confirm brand, availability and final pricing before any purchase." },
  "Seasonal availability": { subject: "Plan your next farm input enquiry", body: "Hello {{name}},\n\nTell us your required farm inputs, quantities and preferred collection date. Availability and suitability need confirmation with the team. This is a captured demonstration message." },
  "Customer service update": { subject: "Your Fatima Agro account", body: "Hello {{name}},\n\nYour customer workspace brings your own enquiries, order requests and support updates together. Sign in to check your records. This is a captured demonstration message." },
};

function Panel({ title, description, children }: { title: string; description?: string; children: ReactNode }) {
  return <section className="ip-panel"><div className="ip-panel-heading"><h2>{title}</h2>{description && <p>{description}</p>}</div>{children}</section>;
}

function DataTable({ rows = [], columns, empty = "No records yet.", caption }: { rows?: object[]; columns: Column[]; empty?: string; caption: string }) {
  if (!rows.length) return <p className="ip-empty">{empty}</p>;
  return <div className="ip-table-wrap" tabIndex={0} aria-label={`${caption}, scroll to see all columns`}><table className="ip-table"><caption>{caption}</caption><thead><tr>{columns.map(column => <th key={column.key} scope="col">{column.label}</th>)}</tr></thead><tbody>{rows.map((item, index) => { const row = item as RecordRow; return <tr key={String(row.id ?? index)}>{columns.map(column => <td key={column.key}>{column.money ? money(row[column.key]) : column.date && row[column.key] ? new Date(String(row[column.key])).toLocaleString("en-GB", { dateStyle: "medium", timeStyle: "short", timeZone: "Africa/Blantyre" }) : text(row[column.key])}</td>)}</tr>; })}</tbody></table></div>;
}

function ActionForm({ title, action, fields = [], capabilities, submitLabel = "Save record", onAction, description, alternateAction, alternateLabel }: { title: string; action: string; fields?: Field[]; capabilities: string[]; submitLabel?: string; onAction: (action: string, data: Record<string, unknown>) => Promise<ActionResponse>; description?: string; alternateAction?: string; alternateLabel?: string }) {
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [result, setResult] = useState<ActionResponse | null>(null);
  const keyRef = useRef<string | null>(null);
  const formRef = useRef<HTMLFormElement>(null);
  const allowed = capabilities.includes(action);
  const available = fields.every(field => !field.options || field.options.length || field.required === false);
  if (!allowed && !(alternateAction && capabilities.includes(alternateAction))) return null;
  function chooseTemplate(value: string) {
    const template = campaignTemplates[value];
    const form = formRef.current;
    if (!template || !form) return;
    const subject = form.elements.namedItem("subject") as HTMLInputElement | null;
    const body = form.elements.namedItem("body") as HTMLTextAreaElement | null;
    if (subject) subject.value = template.subject;
    if (body) body.value = template.body;
  }
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (busy) return;
    const form = event.currentTarget;
    const submitter = (event.nativeEvent as SubmitEvent).submitter as HTMLButtonElement | null;
    const nextAction = submitter?.value || action;
    const formData = new FormData(form);
    const payload: Record<string, unknown> = {};
    for (const field of fields) {
      payload[field.name] = field.type === "number" ? Math.round(Number(formData.get(field.name)) * (field.scale ?? 1)) : field.type === "multiselect" ? formData.getAll(field.name).map(String) : String(formData.get(field.name) ?? "").trim();
      if (field.type === "datetime-local" && payload[field.name]) payload[field.name] = new Date(`${payload[field.name]}+02:00`).toISOString();
    }
    if (nextAction === "finance.payment" || nextAction === "procurement.receive") { keyRef.current ??= crypto.randomUUID(); payload.idempotencyKey = keyRef.current; }
    setBusy(true); setError(""); setResult(null);
    try {
      const response = await onAction(nextAction, payload);
      setResult(response);
      if (nextAction !== "campaign.preview") { form.reset(); keyRef.current = null; }
    } catch (cause) { setError(cause instanceof Error ? cause.message : "The record could not be saved."); }
    finally { setBusy(false); }
  }
  const preview = result?.result && typeof result.result === "object" ? result.result as RecordRow : null;
  return <form className="ip-form" ref={formRef} onSubmit={submit} aria-busy={busy} aria-label={title}><h3>{title}</h3>{description && <p className="ip-form-description">{description}</p>}<div className="ip-fields">{fields.map(field => <label key={field.name} className={field.type === "textarea" ? "ip-field ip-field-wide" : "ip-field"}><span>{field.label}{field.required === false ? " (optional)" : ""}</span>{field.type === "textarea" ? <textarea aria-label={field.label} name={field.name} required={field.required !== false} defaultValue={field.value} rows={3} maxLength={4000} /> : field.options ? <select aria-label={field.label} name={field.name} onChange={field.name === "template" ? event => chooseTemplate(event.target.value) : undefined} required={field.required !== false} multiple={field.type === "multiselect"} defaultValue={field.type === "multiselect" ? [] : field.value ?? ""}>{field.type !== "multiselect" && <option value="">Choose {field.label.toLowerCase()}</option>}{field.options.map(option => <option key={option.value} value={option.value}>{option.label}</option>)}</select> : <input aria-label={field.label} name={field.name} type={field.type ?? "text"} required={field.required !== false} min={field.min} step={field.type === "number" ? field.step ?? 1 : undefined} max={field.type === "number" ? field.max ?? Number.MAX_SAFE_INTEGER : undefined} defaultValue={field.value} maxLength={field.type === "number" ? undefined : 1000} />}{field.hint && <small>{field.hint}</small>}</label>)}</div>{!available && <p className="ip-form-description">Create the required related record first. It will then appear in these choices.</p>}<div className="ip-form-actions">{alternateAction && capabilities.includes(alternateAction) && <button className="ip-button ip-secondary" type="submit" value={alternateAction} disabled={busy || !available}>{busy ? "Working…" : alternateLabel ?? "Preview"}</button>}{allowed && <button className="ip-button" type="submit" value={action} disabled={busy || !available}>{busy ? "Saving…" : submitLabel}</button>}</div>{error && <p role="alert" className="ip-error">{error}</p>}{result && <div className="ip-success" role="status"><p>{result.message}</p>{preview && action === "campaign.create" && <dl>{["recipientCount", "subject", "body", "scheduledAt", "status"].filter(key => preview[key] != null).map(key => <div key={key}><dt>{key === "recipientCount" ? "Recipients" : key === "scheduledAt" ? "Scheduled for" : key[0].toUpperCase() + key.slice(1)}</dt><dd>{text(preview[key])}</dd></div>)}</dl>}</div>}</form>;
}

type ModuleProps = { data: PortalSnapshot; onAction: (action: string, data: Record<string, unknown>) => Promise<ActionResponse>; user: SessionUser };

function Finance({ data, onAction }: ModuleProps) {
  const c = data.capabilities ?? [];
  const invoices = names((data.invoices ?? []).map(item => ({ id: item.id, name: `${money(item.total - item.credited - item.paid)} due` })));
  const bills = names((data.bills ?? []).map(item => ({ id: item.id, name: `${money(item.total - item.paid)} due` })));
  const [paymentKind, setPaymentKind] = useState("customer");
  return <><div className="ip-metrics">{[["Customer balance", data.reports?.receivables], ["Supplier balance", data.reports?.payables], ["Cash book balance", data.reports?.cash], ["Recorded revenue", data.reports?.revenue]].map(([label, value]) => <div key={String(label)}><span>{label}</span><strong>{money(value)}</strong></div>)}</div><p className="ip-notice">Demonstration accounting. Payments, tax treatment and bank matching are captured records. No money moves and no tax return is submitted.</p><TaxConfiguration data={data} onAction={onAction} />
    <Panel title="Customer invoices" description="Customer checkout creates an invoice automatically. You can also record an invoice here."><DataTable rows={data.invoices} caption="Customer invoice register" columns={[{ key: "id", label: "Invoice" }, { key: "customerId", label: "Customer" }, { key: "total", label: "Total", money: true }, { key: "tax", label: "Tax", money: true }, { key: "paid", label: "Paid", money: true }, { key: "credited", label: "Credited", money: true }, { key: "dueDate", label: "Due" }, { key: "status", label: "Status" }]} /><ActionForm title="Record an invoice" action="finance.invoice" fields={[{ name: "customerId", label: "Customer", options: names(data.profiles) }, amountField("total", "Invoice total (MWK)"), amountField("tax", "Tax included (MWK)", 0), { name: "dueDate", label: "Due date", type: "date", value: today() }, { name: "note", label: "Description", type: "textarea" }]} capabilities={c} onAction={onAction} /></Panel>
    <Panel title="Supplier bills"><DataTable rows={data.bills} caption="Supplier bill register" columns={[{ key: "id", label: "Bill" }, { key: "supplierId", label: "Supplier" }, { key: "purchaseOrderId", label: "Purchase order" }, { key: "total", label: "Total", money: true }, { key: "paid", label: "Paid", money: true }, { key: "status", label: "Status" }]} /><ActionForm title="Record a supplier bill" action="finance.bill" fields={[{ name: "supplierId", label: "Supplier", options: names(data.suppliers) }, amountField("total", "Bill total (MWK)"), { name: "note", label: "Description", type: "textarea" }]} capabilities={c} onAction={onAction} /></Panel>
    <Panel title="Payments and numbered receipts" description="Recording a customer payment creates its receipt and updates the account balance.">{c.includes("finance.payment") && <div className="ip-segment" aria-label="Payment kind"><button className={paymentKind === "customer" ? "active" : ""} onClick={() => setPaymentKind("customer")}>Customer payment</button><button className={paymentKind === "supplier" ? "active" : ""} onClick={() => setPaymentKind("supplier")}>Supplier payment</button></div>}<ActionForm key={paymentKind} title={paymentKind === "customer" ? "Capture a customer payment" : "Capture a supplier payment"} action="finance.payment" fields={[{ name: "kind", label: "Payment kind", options: [{ value: paymentKind, label: paymentKind === "customer" ? "Customer" : "Supplier" }], value: paymentKind }, { name: "referenceId", label: paymentKind === "customer" ? "Invoice" : "Bill", options: paymentKind === "customer" ? invoices : bills }, amountField(), { name: "method", label: "Method", options: states(["Cash demonstration", "Bank transfer demonstration", "Mobile money demonstration"]) }, evidenceField]} capabilities={c} submitLabel="Capture payment" onAction={onAction} /><DataTable rows={data.payments} caption="Captured payment register" columns={[{ key: "id", label: "Payment" }, { key: "kind", label: "Kind" }, { key: "referenceId", label: "Invoice / bill" }, { key: "amount", label: "Amount", money: true }, { key: "evidence", label: "Evidence" }, { key: "reconciled", label: "Matched" }]} /><DataTable rows={data.receipts} caption="Numbered customer receipts" columns={[{ key: "id", label: "Receipt" }, { key: "invoiceId", label: "Invoice" }, { key: "paymentId", label: "Payment" }, { key: "amount", label: "Amount", money: true }, { key: "createdAt", label: "Recorded", date: true }]} /></Panel>
    <div className="ip-two-col"><Panel title="Expenses"><DataTable rows={data.expenses} caption="Expense register" columns={[{ key: "id", label: "Expense" }, { key: "category", label: "Category" }, { key: "description", label: "Description" }, { key: "amount", label: "Amount", money: true }, { key: "evidence", label: "Evidence" }]} /><ActionForm title="Record an expense" action="finance.expense" fields={[{ name: "category", label: "Category", options: states(["Transport", "Utilities", "Supplies", "Rent", "Other"]) }, { name: "description", label: "Description" }, amountField(), evidenceField]} capabilities={c} onAction={onAction} /></Panel><Panel title="Credit notes"><DataTable rows={data.creditNotes} caption="Credit note register" columns={[{ key: "id", label: "Credit note" }, { key: "invoiceId", label: "Invoice" }, { key: "amount", label: "Amount", money: true }, { key: "reason", label: "Reason" }]} /><ActionForm title="Issue a credit note" action="finance.credit" fields={[{ name: "invoiceId", label: "Invoice", options: invoices }, amountField(), { name: "reason", label: "Reason", type: "textarea" }]} capabilities={c} onAction={onAction} /></Panel></div>
    <Panel title="Bank statement matching" description="Enter a demonstration statement line, then match it to an equal payment with the same direction."><div className="ip-two-col"><ActionForm title="Add a statement line" action="finance.statement" fields={[{ name: "reference", label: "Statement reference" }, amountField(), { name: "direction", label: "Direction", options: [{ value: "in", label: "Money in" }, { value: "out", label: "Money out" }] }, { name: "date", label: "Statement date", type: "date", value: today() }]} capabilities={c} onAction={onAction} /><ActionForm title="Match payment evidence" action="finance.reconcile" fields={[{ name: "statementId", label: "Unmatched statement line", options: names((data.statementLines ?? []).filter(item => item.status === "Unmatched").map(item => ({ id: item.id, name: `${item.reference}: ${money(item.amount)} ${item.direction}` }))) }, { name: "paymentId", label: "Unmatched payment", options: names((data.payments ?? []).filter(item => !item.reconciled).map(item => ({ id: item.id, name: `${item.kind}: ${money(item.amount)}` }))) }]} capabilities={c} submitLabel="Match records" onAction={onAction} /></div><DataTable rows={data.statementLines} caption="Statement reconciliation" columns={[{ key: "id", label: "Line" }, { key: "reference", label: "Reference" }, { key: "amount", label: "Amount", money: true }, { key: "direction", label: "Direction" }, { key: "date", label: "Date" }, { key: "paymentId", label: "Payment" }, { key: "status", label: "Status" }]} /></Panel>
    <Panel title="Financial reports"><div className="ip-metrics">{[["Expenses", data.reports?.expenses], ["Tax record balance", data.reports?.taxLiability], ["Customer payments", data.reports?.customerPayments], ["Supplier payments", data.reports?.supplierPayments], ["Credit notes", data.reports?.credits]].map(([label, value]) => <div key={String(label)}><span>{label}</span><strong>{money(value)}</strong></div>)}</div><p className="ip-report-check">Journal check: {data.reports?.balanced ? "balanced" : "review required"} · Debits {money(data.reports?.debits)} · Credits {money(data.reports?.journalCredits)}</p><DataTable rows={(data.journals ?? []).flatMap(entry => entry.lines.map((line, index) => ({ id: `${entry.id}-${index}`, reference: entry.reference, description: entry.description, account: line.account, debit: line.debit, credit: line.credit })))} caption="Account movement report" columns={[{ key: "reference", label: "Reference" }, { key: "description", label: "Description" }, { key: "account", label: "Account" }, { key: "debit", label: "Debit", money: true }, { key: "credit", label: "Credit", money: true }]} /></Panel>
  </>;
}

function TaxConfiguration({ data, onAction }: Pick<ModuleProps, "data" | "onAction">) {
  return <Panel title="Product tax records" description="Rates are configurable demonstration inputs. A zero rate marked REVIEW_REQUIRED does not establish an exemption. Qualified review is required before real invoices."><DataTable rows={(data.products ?? []).map(product => ({ id: product.id, name: product.name, taxCode: product.taxCode, percentage: `${product.taxRate / 100}%` }))} caption="Configured demonstration tax treatment" columns={[{ key: "name", label: "Product" }, { key: "taxCode", label: "Tax classification" }, { key: "percentage", label: "Configured rate" }]} /><ActionForm title="Configure demonstration tax treatment" action="finance.taxConfig" fields={[{ name: "productId", label: "Product", options: names(data.products) }, { name: "taxCode", label: "Tax classification or review reference", value: "REVIEW_REQUIRED" }, { name: "taxRate", label: "Rate (%)", type: "number", min: 0, max: 100, step: 0.01, scale: 100, value: "0", hint: "Changes affect future checkout records; existing invoices retain their recorded treatment." }]} capabilities={data.capabilities ?? []} submitLabel="Save demonstration tax setting" onAction={onAction} /></Panel>;
}

function HumanResources({ data, onAction }: ModuleProps) {
  const c = data.capabilities ?? [];
  const employees = names(data.employees);
  return <><p className="ip-notice">Restricted demonstration employee records. Payroll is preparation only: no salary is paid and no PAYE submission is made.</p><Panel title="Employee records"><DataTable rows={data.employees} caption="Restricted employee register" columns={[{ key: "id", label: "Employee" }, { key: "name", label: "Name" }, { key: "roleTitle", label: "Role" }, { key: "unitId", label: "Unit" }, { key: "workEmail", label: "Work email" }, { key: "startDate", label: "Start date" }, { key: "salary", label: "Gross monthly pay", money: true }, { key: "status", label: "Status" }]} /><ActionForm title="Add a demonstration employee" action="hr.employee" fields={[{ name: "name", label: "Employee name" }, { name: "roleTitle", label: "Role title" }, { name: "unitId", label: "Operating unit", options: names(data.units) }, { name: "workEmail", label: "Work email", type: "email", hint: "Use a synthetic address ending in .test." }, { name: "startDate", label: "Start date", type: "date", value: today() }, amountField("salary", "Gross monthly pay (MWK)", 0)]} capabilities={c} onAction={onAction} /></Panel><Panel title="Onboarding"><DataTable rows={data.employees} caption="Onboarding checks" columns={[{ key: "name", label: "Employee" }, { key: "onboarding", label: "Completed checks" }, { key: "status", label: "Status" }]} /><ActionForm title="Complete an onboarding check" action="hr.onboarding" fields={[{ name: "employeeId", label: "Employee", options: employees }, { name: "check", label: "Completed check", options: states(["Identity verification", "Contract review", "Safety induction", "System access review"]) }]} capabilities={c} submitLabel="Record completed check" onAction={onAction} /></Panel><Panel title="Leave requests"><DataTable rows={data.leaveRequests} caption="Leave register" columns={[{ key: "id", label: "Request" }, { key: "employeeId", label: "Employee" }, { key: "from", label: "From" }, { key: "to", label: "To" }, { key: "reason", label: "Reason" }, { key: "status", label: "Decision" }, { key: "approvedBy", label: "Approver" }]} /><div className="ip-two-col"><ActionForm title="Request leave" action="hr.leave" fields={[{ name: "employeeId", label: "Employee", options: employees }, { name: "from", label: "From", type: "date", value: today() }, { name: "to", label: "To", type: "date", value: today() }, { name: "reason", label: "Reason", type: "textarea" }]} capabilities={c} submitLabel="Submit request" onAction={onAction} /><ActionForm title="Review leave" action="hr.leaveDecision" fields={[{ name: "leaveId", label: "Pending leave request", options: names((data.leaveRequests ?? []).filter(item => item.status === "Pending").map(item => ({ id: item.id, name: `${item.employeeId}: ${item.from} to ${item.to}` }))) }, { name: "decision", label: "Decision", options: states(["Approved", "Declined"]) }]} description="A separate authorised approver must decide the request." capabilities={c} submitLabel="Record decision" onAction={onAction} /></div></Panel><div className="ip-two-col"><Panel title="Attendance"><DataTable rows={data.attendance} caption="Attendance register" columns={[{ key: "employeeId", label: "Employee" }, { key: "date", label: "Date" }, { key: "status", label: "Attendance" }]} /><ActionForm title="Record attendance" action="hr.attendance" fields={[{ name: "employeeId", label: "Employee", options: employees }, { name: "date", label: "Date", type: "date", value: today() }, { name: "status", label: "Attendance", options: states(["Present", "Absent", "Leave"]) }]} capabilities={c} onAction={onAction} /></Panel><Panel title="Payroll preparation"><DataTable rows={data.payrollPreparations} caption="Payroll preparation register" columns={[{ key: "id", label: "Preparation" }, { key: "period", label: "Period" }, { key: "gross", label: "Gross", money: true }, { key: "deductions", label: "Entered deductions", money: true }, { key: "net", label: "Net", money: true }, { key: "status", label: "Status" }]} /><ActionForm title="Prepare a payroll summary" action="hr.payroll" description="Select employees and enter reviewed deductions. This does not calculate statutory tax or release pay." fields={[{ name: "period", label: "Pay period", type: "month", value: today().slice(0, 7) }, { name: "employeeIds", label: "Employees", type: "multiselect", options: employees, hint: "Select one or more employees." }, amountField("deductions", "Reviewed total deductions (MWK)", 0)]} capabilities={c} submitLabel="Prepare summary" onAction={onAction} /></Panel></div></>;
}

function OrderManagement({ data, onAction }: ModuleProps) {
  const [selectedId, setSelectedId] = useState("");
  const c = data.capabilities ?? [];
  const openOrders = (data.orders ?? []).filter(order => !["Completed", "Cancelled"].includes(order.status));
  const selected = openOrders.find(order => order.id === selectedId) ?? openOrders[0];
  const nextStatuses: Record<string, string[]> = { "Awaiting confirmation": ["Confirmed", "Cancelled"], Confirmed: ["Ready for collection", "Dispatched", "Cancelled"], "Ready for collection": ["Completed"], Dispatched: ["Completed"] };
  if (!data.orders || !c.includes("order.status")) return null;
  return <Panel title="Customer order fulfilment" description="Confirm requests, record preparation and update customer tracking. Payment must be recorded before fulfilment."><DataTable rows={data.orders} caption="Customer order register" columns={[{ key: "id", label: "Order" }, { key: "customerId", label: "Customer" }, { key: "unitId", label: "Unit" }, { key: "fulfilment", label: "Collection / delivery" }, { key: "deliveryAddress", label: "Delivery details" }, { key: "contact", label: "Contact" }, { key: "total", label: "Total", money: true }, { key: "status", label: "Status" }]} />{c.includes("order.status") && <div className="ip-order-picker"><label className="ip-field"><span>Order to update</span><select value={selected?.id ?? ""} onChange={event => setSelectedId(event.target.value)}>{!openOrders.length && <option value="">No open orders</option>}{openOrders.map(order => <option key={order.id} value={order.id}>{order.id} · {order.status}</option>)}</select></label></div>}{selected && <><DataTable rows={selected.lines} caption={`Product lines for ${selected.id}`} columns={[{ key: "name", label: "Product" }, { key: "quantity", label: "Quantity" }, { key: "unitPrice", label: "Unit price", money: true }, { key: "total", label: "Line total", money: true }]} /><ActionForm key={selected.id} title="Update customer tracking" action="order.status" fields={[{ name: "orderId", label: "Order", options: [{ value: selected.id, label: selected.id }], value: selected.id }, { name: "status", label: "Next status", options: states(nextStatuses[selected.status] ?? []) }, { name: "note", label: "Customer tracking note", type: "textarea", hint: "Use clear information the customer can see. Delivery is simulated." }]} capabilities={c} submitLabel="Update order status" onAction={onAction} /></>}</Panel>;
}

function Procurement({ data, onAction, user }: ModuleProps) {
  const c = data.capabilities ?? [];
  if (user.role === "sales") return <><p className="ip-notice">Demonstration fulfilment. Status updates are visible to the customer; no delivery partner is contacted.</p><OrderManagement data={data} onAction={onAction} user={user} /><CustomerRequests data={data} onAction={onAction} /></>;
  return <><p className="ip-notice">Demonstration procurement. Purchase orders are recorded here and are not sent to suppliers. Receiving stock creates a movement and a matching supplier bill.</p><OrderManagement data={data} onAction={onAction} user={user} /><CustomerRequests data={data} onAction={onAction} /><Panel title="Stock availability"><DataTable rows={data.products} caption="Catalogue stock balances" columns={[{ key: "id", label: "Product" }, { key: "name", label: "Name" }, { key: "pack", label: "Pack" }, { key: "stock", label: "Available units" }, { key: "reorderLevel", label: "Reorder level" }]} /></Panel><Panel title="Suppliers"><DataTable rows={data.suppliers} caption="Supplier register" columns={[{ key: "id", label: "Supplier" }, { key: "name", label: "Name" }, { key: "email", label: "Email" }, { key: "contact", label: "Contact" }, { key: "status", label: "Status" }]} /><ActionForm title="Add a demonstration supplier" action="procurement.supplier" fields={[{ name: "name", label: "Supplier name" }, { name: "email", label: "Email", type: "email" }, { name: "contact", label: "Contact reference" }]} capabilities={c} onAction={onAction} /></Panel><Panel title="Purchase requests"><DataTable rows={data.purchaseRequests} caption="Purchase request register" columns={[{ key: "id", label: "Request" }, { key: "productId", label: "Product" }, { key: "quantity", label: "Quantity" }, { key: "unitId", label: "Unit" }, { key: "neededBy", label: "Needed by" }, { key: "evidence", label: "Evidence" }, { key: "status", label: "Status" }]} /><div className="ip-two-col"><ActionForm title="Request stock" action="procurement.request" fields={[{ name: "productId", label: "Product", options: names(data.products) }, amountField("quantity", "Quantity"), { name: "unitId", label: "Operating unit", options: names(data.units) }, { name: "neededBy", label: "Needed by", type: "date", value: today() }, evidenceField]} capabilities={c} submitLabel="Submit purchase request" onAction={onAction} /><ActionForm title="Review a purchase request" action="procurement.approve" description="The requester cannot approve their own request." fields={[{ name: "requestId", label: "Pending request", options: names((data.purchaseRequests ?? []).filter(item => item.status === "Pending").map(item => ({ id: item.id, name: `${item.productId} × ${item.quantity}` }))) }, { name: "decision", label: "Decision", options: states(["Approved", "Declined"]) }]} capabilities={c} submitLabel="Record decision" onAction={onAction} /></div></Panel><Panel title="Purchase orders and goods received"><div className="ip-two-col"><ActionForm title="Create a purchase order" action="procurement.order" fields={[{ name: "requestId", label: "Approved request", options: names((data.purchaseRequests ?? []).filter(item => item.status === "Approved").map(item => ({ id: item.id, name: `${item.productId} × ${item.quantity}` }))) }, { name: "supplierId", label: "Supplier", options: names(data.suppliers) }, amountField("unitPrice", "Price per unit (MWK)")]} capabilities={c} submitLabel="Create demonstration order" onAction={onAction} /><ActionForm title="Record goods received" action="procurement.receive" fields={[{ name: "purchaseOrderId", label: "Open purchase order", options: names((data.purchaseOrders ?? []).filter(item => item.received < item.quantity).map(item => ({ id: item.id, name: `${item.productId}: ${item.quantity - item.received} remaining` }))) }, amountField("quantity", "Quantity received"), evidenceField]} capabilities={c} submitLabel="Receive and update stock" onAction={onAction} /></div><DataTable rows={data.purchaseOrders} caption="Purchase order register" columns={[{ key: "id", label: "Order" }, { key: "requestId", label: "Request" }, { key: "supplierId", label: "Supplier" }, { key: "productId", label: "Product" }, { key: "quantity", label: "Ordered" }, { key: "received", label: "Received" }, { key: "unitPrice", label: "Unit price", money: true }, { key: "status", label: "Status" }]} /><DataTable rows={data.goodsReceipts} caption="Goods received register" columns={[{ key: "id", label: "Receipt" }, { key: "purchaseOrderId", label: "Purchase order" }, { key: "productId", label: "Product" }, { key: "quantity", label: "Quantity" }, { key: "evidence", label: "Evidence" }, { key: "billId", label: "Created bill" }]} /></Panel><Panel title="Stock movement history"><DataTable rows={data.stockMovements} caption="Inventory movements" columns={[{ key: "id", label: "Movement" }, { key: "productId", label: "Product" }, { key: "quantity", label: "Change" }, { key: "reason", label: "Reason" }, { key: "reference", label: "Source" }, { key: "unitId", label: "Unit" }, { key: "at", label: "Recorded", date: true }]} /></Panel></>;
}

function CustomerRequests({ data, onAction }: Pick<ModuleProps, "data" | "onAction">) {
  const c = data.capabilities ?? [];
  if (!c.includes("enquiry.respond") && !c.includes("support.respond")) return null;
  return <><Panel title="Customer enquiries" description="Respond to the customer's question and record the follow-up in their account."><DataTable rows={data.enquiries} caption="Customer enquiry inbox" columns={[{ key: "id", label: "Enquiry" }, { key: "name", label: "Customer" }, { key: "subject", label: "Subject" }, { key: "productId", label: "Product" }, { key: "quantity", label: "Quantity" }, { key: "message", label: "Question" }, { key: "response", label: "Response" }, { key: "status", label: "Status" }]} /><ActionForm title="Respond to an enquiry" action="enquiry.respond" fields={[{ name: "enquiryId", label: "Customer enquiry", options: names((data.enquiries ?? []).map(item => ({ id: item.id, name: `${item.name}: ${item.subject || item.message.slice(0, 60)}` }))) }, { name: "response", label: "Customer response", type: "textarea", hint: "For signed-in customers this appears in their account. Email is captured only." }]} capabilities={c} submitLabel="Record enquiry response" onAction={onAction} /></Panel><Panel title="Account support" description="Answer account requests using clear customer-facing information."><DataTable rows={data.supportRequests} caption="Account support inbox" columns={[{ key: "id", label: "Request" }, { key: "customerId", label: "Customer" }, { key: "subject", label: "Subject" }, { key: "message", label: "Question" }, { key: "response", label: "Response" }, { key: "status", label: "Status" }]} /><ActionForm title="Answer a support request" action="support.respond" fields={[{ name: "supportId", label: "Support request", options: names((data.supportRequests ?? []).map(item => ({ id: item.id, name: item.subject }))) }, { name: "response", label: "Support response", type: "textarea" }]} capabilities={c} submitLabel="Record support response" onAction={onAction} /></Panel></>;
}

function ReviewModeration({ data, onAction }: Pick<ModuleProps, "data" | "onAction">) {
  return <Panel title="Customer review moderation" description="Only customer reviews submitted with publication consent may be published. Reviews remain labelled as demonstration feedback."><DataTable rows={data.reviews} caption="Customer review register" columns={[{ key: "id", label: "Review" }, { key: "name", label: "Public display name" }, { key: "rating", label: "Rating out of 5" }, { key: "text", label: "Review" }, { key: "publicationConsent", label: "Publication consent" }, { key: "status", label: "Status" }]} /><ActionForm title="Review publication decision" action="review.moderate" fields={[{ name: "reviewId", label: "Consented review", options: names((data.reviews ?? []).filter(item => item.publicationConsent).map(item => ({ id: item.id, name: `${item.name}: ${item.text.slice(0, 65)}` }))) }, { name: "decision", label: "Decision", options: states(["Published", "Declined"]) }]} capabilities={data.capabilities ?? []} submitLabel="Save review decision" onAction={onAction} /></Panel>;
}

function Administration({ data, onAction }: ModuleProps) {
  const c = data.capabilities ?? [];
  const roleOptions = states(["sales", "storekeeper", "procurement", "finance", "finance-director", "hr", "hr-director", "operations-director", "branch-manager", "communications", "administrator", "ceo"]).map(option => ({ ...option, label: option.value === "ceo" ? "CEO operating approver" : option.value.replaceAll("-", " ").replace(/(^|\s)\S/g, letter => letter.toUpperCase()) }));
  return <><p className="ip-notice">Headquarters retains core management functions. A branch or depot receives only its approved functions and access. Technical administrators do not approve routine business transactions.</p><Panel title="Branches, depots and headquarters"><DataTable rows={data.units} caption="Operating unit register" columns={[{ key: "id", label: "Unit" }, { key: "name", label: "Name" }, { key: "kind", label: "Type" }, { key: "functions", label: "Functions" }, { key: "evidence", label: "Evidence" }, { key: "status", label: "Status" }]} /><div className="ip-two-col"><ActionForm title="Create an operating unit" action="admin.unit" fields={[{ name: "name", label: "Unit name" }, { name: "kind", label: "Unit type", options: states(["Branch", "Depot"]) }, { name: "functions", label: "Requested functions", type: "multiselect", options: states(["Sales", "Inventory", "Procurement requests", "Tasks", "MRA source evidence"]) }, evidenceField]} capabilities={c} submitLabel="Create setup record" onAction={onAction} /><ActionForm title="Approve unit activation" action="admin.activateUnit" fields={[{ name: "unitId", label: "Unit in setup", options: names((data.units ?? []).filter(item => item.status === "Setup")) }]} capabilities={c} submitLabel="Activate unit" onAction={onAction} /></div></Panel><Panel title="Access requests and director approval"><DataTable rows={data.roleRequests} caption="Role approval register" columns={[{ key: "id", label: "Request" }, { key: "email", label: "Account" }, { key: "role", label: "Requested role" }, { key: "unitId", label: "Unit" }, { key: "reason", label: "Reason" }, { key: "approverRole", label: "Required approver" }, { key: "status", label: "Status" }]} /><div className="ip-two-col"><ActionForm title="Request role access" action="admin.roleRequest" fields={[{ name: "userId", label: "Account", options: names(data.users) }, { name: "role", label: "Requested role", options: roleOptions }, { name: "unitId", label: "Operating unit", options: names(data.units) }, { name: "reason", label: "Business reason", type: "textarea" }]} capabilities={c} submitLabel="Submit for director approval" onAction={onAction} /><ActionForm title="Review access request" action="admin.roleDecision" description="The required director must review the request; self-approval is prevented." fields={[{ name: "requestId", label: "Pending access request", options: names((data.roleRequests ?? []).filter(item => item.status === "Pending director approval").map(item => ({ id: item.id, name: `${item.email}: ${item.role}` }))) }, { name: "decision", label: "Decision", options: states(["Approved", "Declined"]) }]} capabilities={c} submitLabel="Record director decision" onAction={onAction} /></div><ActionForm title="Apply approved access" action="admin.applyRole" fields={[{ name: "requestId", label: "Approved access request", options: names((data.roleRequests ?? []).filter(item => item.status === "Approved").map(item => ({ id: item.id, name: `${item.email}: ${item.role}` }))) }]} capabilities={c} submitLabel="Apply approved role" onAction={onAction} /><DataTable rows={data.users} caption="Authorised user directory" columns={[{ key: "id", label: "User" }, { key: "name", label: "Name" }, { key: "email", label: "Account" }, { key: "role", label: "Role" }, { key: "unitId", label: "Unit" }]} /></Panel><Panel title="Tasks and evidence"><DataTable rows={data.tasks} caption="Unit task register" columns={[{ key: "id", label: "Task" }, { key: "title", label: "Task" }, { key: "unitId", label: "Unit" }, { key: "owner", label: "Owner" }, { key: "due", label: "Due" }, { key: "evidence", label: "Evidence" }, { key: "status", label: "Status" }]} /><div className="ip-two-col"><ActionForm title="Assign an operating task" action="admin.task" fields={[{ name: "title", label: "Task" }, { name: "unitId", label: "Operating unit", options: names(data.units) }, { name: "owner", label: "Responsible person or role" }, { name: "due", label: "Due date", type: "date", value: today() }]} capabilities={c} onAction={onAction} /><ActionForm title="Submit task evidence" action="admin.taskEvidence" fields={[{ name: "taskId", label: "Open task", options: names((data.tasks ?? []).filter(item => item.status === "Open").map(item => ({ id: item.id, name: item.title }))) }, evidenceField]} capabilities={c} submitLabel="Submit evidence" onAction={onAction} /></div><ActionForm title="Review completed task" action="admin.taskApprove" fields={[{ name: "taskId", label: "Submitted task", options: names((data.tasks ?? []).filter(item => item.status === "Submitted").map(item => ({ id: item.id, name: item.title }))) }]} capabilities={c} submitLabel="Approve task evidence" onAction={onAction} /></Panel><Panel title="Audit trail" description="Actions are time stamped and linked to the acting account, role and operating unit."><DataTable rows={data.audit} caption="Company audit events" columns={[{ key: "at", label: "Time", date: true }, { key: "actorId", label: "Account" }, { key: "actorRole", label: "Role" }, { key: "action", label: "Action" }, { key: "target", label: "Record" }, { key: "unitId", label: "Unit" }, { key: "outcome", label: "Outcome" }]} /></Panel>{c.includes("admin.reset") && <Panel title="Reset the local presentation" description="This clears this local demonstration's transactions and restores the starting records. It is restricted to local demonstration administrators."><ResetDemo onAction={onAction} capabilities={c} /></Panel>}</>;
}

function ResetDemo({ onAction, capabilities }: { onAction: ModuleProps["onAction"]; capabilities: string[] }) {
  const [confirmed, setConfirmed] = useState(false);
  return <><label className="ip-check"><input type="checkbox" checked={confirmed} onChange={event => setConfirmed(event.target.checked)} /> I intend to clear the local demonstration records.</label>{confirmed && <ActionForm title="Restore starting data" action="admin.reset" fields={[{ name: "confirmation", label: "Type RESET SYNTHETIC DEMONSTRATION to confirm", value: "" }]} capabilities={capabilities} submitLabel="Reset local demonstration" onAction={onAction} />}</>;
}

function Communications({ data, onAction }: ModuleProps) {
  const c = [...(data.capabilities ?? []), "communication.unsubscribe"];
  return <><p className="ip-notice">Safe demonstration mode. Messages are captured for review and are never sent. A real campaign needs a configured provider, recorded consent and an explicit authorised send action.</p><Panel title="Prepare a campaign" description="Preview the audience and message before saving. Duplicate capture is prevented and unsubscribed customers are excluded."><ActionForm title="Campaign details" action="campaign.create" alternateAction="campaign.preview" alternateLabel="Preview recipients and message" submitLabel="Save campaign" fields={[{ name: "name", label: "Campaign name" }, { name: "audience", label: "Audience", options: [{ value: "test-recipients", label: "Demonstration test recipients" }, { value: "consented-customers", label: "Customers with marketing consent" }] }, { name: "template", label: "Template", options: states(["Product update", "Seasonal availability", "Customer service update"]) }, { name: "subject", label: "Subject" }, { name: "body", label: "Message", type: "textarea", hint: "An unsubscribe instruction is included in captured campaigns." }, { name: "scheduledAt", label: "Capture schedule (Malawi time, UTC+2)", type: "datetime-local", required: false, hint: "Leave blank for a manual capture. Scheduled messages are processed by the action below." }]} capabilities={c} onAction={onAction} /></Panel><Panel title="Campaign status"><DataTable rows={data.campaigns} caption="Campaign register" columns={[{ key: "id", label: "Campaign" }, { key: "name", label: "Name" }, { key: "audience", label: "Audience" }, { key: "recipientCount", label: "Recipients" }, { key: "scheduledAt", label: "Schedule (Malawi time)", date: true }, { key: "status", label: "Status" }, { key: "capturedAt", label: "Captured", date: true }]} /><div className="ip-two-col"><ActionForm title="Capture a saved campaign" action="campaign.capture" fields={[{ name: "campaignId", label: "Uncaptured campaign", options: names((data.campaigns ?? []).filter(item => item.status !== "Captured").map(item => ({ id: item.id, name: item.name }))) }]} capabilities={c} submitLabel="Capture test messages" onAction={onAction} /><ActionForm title="Process scheduled captures" action="campaign.processDue" description="Captures only campaigns whose scheduled time has arrived. No external mail is sent." capabilities={c} submitLabel="Process due captures" onAction={onAction} /></div></Panel><Panel title="Consent and unsubscribe"><DataTable rows={data.profiles} caption="Customer communication preferences" columns={[{ key: "id", label: "Customer" }, { key: "name", label: "Name" }, { key: "marketingConsent", label: "Marketing consent" }, { key: "unsubscribed", label: "Unsubscribed" }]} /><ActionForm title="Record an unsubscribe" action="communication.unsubscribe" fields={[{ name: "customerId", label: "Customer", options: names(data.profiles) }]} capabilities={c} submitLabel="Unsubscribe customer" onAction={onAction} /></Panel><ReviewModeration data={data} onAction={onAction} /><Panel title="Captured message evidence" description="This register shows captured messages, not delivery to an inbox."><DataTable rows={data.capturedMessages} caption="Captured message register" columns={[{ key: "id", label: "Message" }, { key: "to", label: "Test recipient" }, { key: "subject", label: "Subject" }, { key: "kind", label: "Kind" }, { key: "campaignId", label: "Campaign" }, { key: "status", label: "Delivery status" }, { key: "createdAt", label: "Captured", date: true }]} />{(data.capturedMessages ?? []).map(message => <details className="ip-message-details" key={message.id}><summary>{message.subject} · {message.to}</summary><p>{message.body}</p>{message.kind === "campaign" && <Link href={`/unsubscribe?token=${encodeURIComponent(message.unsubscribeToken)}`}>Open unsubscribe preference</Link>}</details>)}</Panel></>;
}

function Notifications({ data, onAction, user }: ModuleProps) {
  const [working, setWorking] = useState("");
  const [error, setError] = useState("");
  async function markRead(id: string) { setWorking(id); setError(""); try { await onAction("notification.read", { notificationId: id }); } catch (cause) { setError(cause instanceof Error ? cause.message : "Could not update notification."); } finally { setWorking(""); } }
  return <><div className="ip-workspaces">{Object.entries(moduleInfo).filter(([key, info]) => key !== "notifications" && info.roles.includes(user.role)).map(([key, info]) => <Link key={key} href={`/hq/${key}`} className="ip-workspace"><h2>{info.title}<span aria-hidden="true">→</span></h2><p>{info.description}</p><span>Open workspace</span></Link>)}</div><Panel title="Notification centre" description="Account, order, approval and stock events relevant to your access.">{error && <p className="ip-error" role="alert">{error}</p>}{!data.notifications?.length ? <p className="ip-empty">You have no notifications yet. New events will appear here.</p> : <ul className="ip-notifications">{data.notifications.map(item => { const read = item.readBy.includes(user.id); return <li key={item.id} className={read ? "is-read" : ""}><div><span className="ip-event">{item.event}</span><h3>{item.title}</h3><p>{item.body}</p><time dateTime={item.createdAt}>{new Date(item.createdAt).toLocaleString("en-GB", { timeZone: "Africa/Blantyre" })}</time></div>{read ? <span className="ip-status">Read</span> : <button className="ip-button ip-secondary" onClick={() => markRead(item.id)} disabled={!!working}>{working === item.id ? "Updating…" : "Mark read"}</button>}</li>; })}</ul>}</Panel></>;
}

export default function InternalPortal({ module, initialUser }: { module: InternalModule; initialUser: SessionUser }) {
  const [data, setData] = useState<PortalSnapshot | null>(null);
  const [session, setSession] = useState<SessionResponse | null>(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [accessNotice, setAccessNotice] = useState(false);
  const [actionMessage, setActionMessage] = useState("");
  const activeRequest = useRef(0);
  const reload = useCallback(async () => {
    const requestId = ++activeRequest.current;
    const response = await fetch(`/api/portal?module=${encodeURIComponent(module)}`, { cache: "no-store", credentials: "same-origin" });
    const payload = await response.json() as PortalSnapshot & { error?: string };
    if (!response.ok) throw new Error(payload.error ?? "This workspace could not be loaded.");
    if (requestId === activeRequest.current) setData(payload as PortalSnapshot);
  }, [module]);
  useEffect(() => {
    let active = true;
    Promise.all([reload(), fetch("/api/session", { cache: "no-store", credentials: "same-origin" }).then(async response => await response.json() as SessionResponse).then((response: SessionResponse) => { if (active) setSession(response); })]).then(() => { if (active) setAccessNotice(new URLSearchParams(window.location.search).get("denied") === "1"); }).catch(cause => { if (active) setError(cause instanceof Error ? cause.message : "Unable to load workspace."); }).finally(() => { if (active) setLoading(false); });
    return () => { active = false; activeRequest.current++; };
  }, [reload]);
  const act = useCallback(async (action: string, body: Record<string, unknown>) => {
    setActionMessage("");
    const response = await fetch(`/api/portal?module=${encodeURIComponent(module)}`, { method: "POST", credentials: "same-origin", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action, data: body }) });
    const result = await response.json() as ActionResponse & { error?: string };
    if (!response.ok) throw new Error(result.error ?? "The action was not completed. Check your access and the entered values.");
    setActionMessage(result.message);
    if (action !== "campaign.preview") {
      try { await reload(); }
      catch { setError("The record was saved. Refresh records to load the latest view."); }
    }
    return result as ActionResponse;
  }, [module, reload]);
  async function refresh() { setRefreshing(true); setError(""); try { await reload(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Could not refresh."); } finally { setRefreshing(false); } }
  const info = moduleInfo[module];
  const user = session?.user ?? initialUser;
  return <div className="ip-shell"><aside className="ip-sidebar"><Link href="/hq" className="ip-brand"><span className="ip-brand-mark">FA</span><span><strong>Fatima Agro</strong><small>Headquarters · Core system</small></span></Link><p className="ip-nav-label">Organisation workspace</p><nav aria-label="Internal workspaces">{Object.entries(moduleInfo).filter(([key, item]) => key === "notifications" || item.roles.includes(user.role)).map(([key, item]) => <Link key={key} href={key === "notifications" ? "/hq" : `/hq/${key}`} aria-current={key === module ? "page" : undefined}>{item.title}</Link>)}</nav><div className="ip-sidebar-bottom"><p>Access is scoped to your role and operating unit.</p><Link href="/">Public website ↗</Link></div></aside><div className="ip-main"><header className="ip-topbar"><span className="ip-demo-badge">Demonstration environment</span><div><span>{user.name}<small>{user.role.replaceAll("-", " ")} · {user.unitId}</small></span><Link className="ip-account-link" href="/account">Account</Link></div></header><main id="main-content" className="ip-content"><div className="ip-title"><div><p className="ip-eyebrow">Fatima Agro · Internal</p><h1>{info.title}</h1><p>{info.description}</p></div><button className="ip-button ip-secondary" onClick={refresh} disabled={loading || refreshing}>{refreshing ? "Refreshing…" : "Refresh records"}</button></div>{actionMessage && <p className="ip-success" role="status">{actionMessage}</p>}{accessNotice && <p className="ip-notice" role="status">That workspace is outside your approved role. Your permitted workspaces are shown here.</p>}{error && <div className="ip-error" role="alert"><p>{error}</p><Link href="/account">Review your sign-in and access</Link></div>}{loading ? <div className="ip-loading" role="status"><span />Loading your authorised records…</div> : data && <>{module === "finance" && <Finance data={data} onAction={act} user={user} />}{module === "hr" && <HumanResources data={data} onAction={act} user={user} />}{module === "procurement" && <Procurement data={data} onAction={act} user={user} />}{module === "admin" && <Administration data={data} onAction={act} user={user} />}{module === "communications" && <Communications data={data} onAction={act} user={user} />}{module === "notifications" && <Notifications data={data} onAction={act} user={user} />}<footer className="ip-footer"><span>Synthetic demonstration records · Revision {data.revision}</span><span>Company clock: Africa/Blantyre (UTC+2)</span></footer></>}</main></div></div>;
}
